CREATE TABLE public.telegram_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, user_id uuid NOT NULL, name text NOT NULL, amount_paise integer NOT NULL CHECK(amount_paise BETWEEN 100 AND 10000000), credits integer NOT NULL CHECK(credits BETWEEN 1 AND 1000000), days integer NOT NULL CHECK(days BETWEEN 1 AND 365), tier text NOT NULL CHECK(tier IN ('creator','pro','premium')), reason text NOT NULL, status text NOT NULL DEFAULT 'draft', order_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours');
GRANT SELECT ON public.telegram_offers TO authenticated;
GRANT ALL ON public.telegram_offers TO service_role;
ALTER TABLE public.telegram_offers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own or owner offers" ON public.telegram_offers FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'::public.app_role));
ALTER TABLE public.payments ADD COLUMN telegram_offer_id uuid REFERENCES public.telegram_offers(id);
CREATE OR REPLACE FUNCTION public.telegram_confirm_offer(_id uuid,_sender text,_chat text,_approve boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.telegram_admin_config; o public.telegram_offers; ord text; BEGIN SELECT * INTO c FROM public.telegram_admin_config WHERE id=true FOR UPDATE; IF NOT c.enabled OR c.owner_verified_at IS NULL OR c.owner_telegram_id<>_sender OR (_chat<>c.owner_telegram_id AND _chat<>c.admin_chat_id) OR NOT public.has_role(c.website_owner_id,'admin'::public.app_role) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; SELECT * INTO o FROM public.telegram_offers WHERE id=_id FOR UPDATE; IF o.id IS NULL OR o.owner_id<>c.website_owner_id THEN RAISE EXCEPTION 'OFFER_NOT_FOUND'; END IF; IF o.status<>'draft' THEN RETURN jsonb_build_object('status',o.status,'order_id',o.order_id,'already_decided',true); END IF; IF o.expires_at<now() THEN UPDATE public.telegram_offers SET status='expired' WHERE id=o.id; RETURN jsonb_build_object('status','expired'); END IF; IF NOT _approve THEN UPDATE public.telegram_offers SET status='cancelled' WHERE id=o.id; RETURN jsonb_build_object('status','cancelled'); END IF; IF c.original_qr_file_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.telegram_account_links WHERE website_user_id=o.user_id) THEN RAISE EXCEPTION 'ORIGINAL_QR_AND_LINK_REQUIRED'; END IF; ord:='MN-TG-'||replace(o.id::text,'-',''); INSERT INTO public.payments(user_id,plan,amount_paise,currency,order_id,payment_method,status,credits,telegram_offer_id) VALUES(o.user_id,o.tier,o.amount_paise,'INR',ord,'upi_manual','pending',o.credits,o.id); UPDATE public.telegram_offers SET status='pending_payment',order_id=ord WHERE id=o.id; INSERT INTO public.admin_audit_log(admin_id,action,target_user,reason,related_id,details) VALUES(c.website_owner_id,'telegram_custom_offer',o.user_id,o.reason,ord,jsonb_build_object('offer_id',o.id,'amount_paise',o.amount_paise,'credits',o.credits,'days',o.days,'tier',o.tier)); RETURN jsonb_build_object('status','pending_payment','order_id',ord); END; $$;
REVOKE ALL ON FUNCTION public.telegram_confirm_offer(uuid,text,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.telegram_confirm_offer(uuid,text,text,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.telegram_submit_utr(_order text,_sender text,_utr text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pay public.payments; uid uuid; BEGIN IF _utr !~ '^[0-9]{12}$' THEN RAISE EXCEPTION 'INVALID_UTR'; END IF; SELECT website_user_id INTO uid FROM public.telegram_account_links WHERE telegram_user_id=_sender; SELECT * INTO pay FROM public.payments WHERE order_id=_order FOR UPDATE; IF uid IS NULL OR pay.user_id<>uid OR pay.status<>'pending' OR pay.payment_method<>'upi_manual' THEN RAISE EXCEPTION 'ORDER_UNAVAILABLE'; END IF; IF pay.provider_payment_id IS NOT NULL AND pay.provider_payment_id<>_utr THEN RAISE EXCEPTION 'UTR_ALREADY_SUBMITTED'; END IF; UPDATE public.payments SET provider_payment_id=_utr WHERE id=pay.id; RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.telegram_submit_utr(text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.telegram_submit_utr(text,text,text) TO service_role;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.activate_payment(text,text,text,integer)'::regprocedure) INTO d; IF position('IF p.status IN (''refunded'') THEN RAISE EXCEPTION ''ORDER_CLOSED''; END IF;' IN d)=0 THEN RAISE EXCEPTION 'ACTIVATION_CHANGED'; END IF; d:=replace(d,'IF p.status IN (''refunded'') THEN RAISE EXCEPTION ''ORDER_CLOSED''; END IF;','IF p.status <> ''pending'' THEN RAISE EXCEPTION ''ORDER_CLOSED''; END IF; IF p.telegram_offer_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.telegram_offers WHERE id=p.telegram_offer_id AND status=''pending_payment'' AND expires_at>now() AND user_id=p.user_id AND amount_paise=p.amount_paise AND credits=p.credits AND tier=p.plan) THEN RAISE EXCEPTION ''OFFER_EXPIRED_OR_CHANGED''; END IF; SELECT now()+days*interval ''1 day'' INTO e FROM public.telegram_offers WHERE id=p.telegram_offer_id; UPDATE public.telegram_offers SET status=''paid'' WHERE id=p.telegram_offer_id; END IF;'); EXECUTE d; END; $$;
REVOKE ALL ON FUNCTION public.activate_payment(text,text,text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.activate_payment(text,text,text,integer) TO service_role;